#include "reduction.hpp"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <filesystem>
using namespace work_reduction;
namespace fs=std::filesystem;
void validate(const fs::path&dir){std::ofstream out(dir/"validation.csv");out<<"case,extension,objective_gradient_error,objective_hessian_error,map_balance_error,cycle_rank,pass\n";for(std::string name:{"scalar_mixed","radial_orbit","elastic_mixed","chain_mixed"})for(std::string extension:{"balanced","grounded_first","grounded_last"}){
 auto c=make_case(name);double E=std::max(1e-6,energy(c.model,c.initial)-minimum_energy(c.model));auto cfg=configuration("implicit_midpoint_dg");CrossProblem f(c.model,c.initial,1./60,cfg,E,"implicit_midpoint_dg",true);Reduced p(f,extension);V q=p.midpoint_initial();for(int i=0;i<q.size();++i)q[i]+=.03*std::sin(i+1);auto e=p.evaluate(q);double ge=0,he=0;for(int i=0;i<q.size();++i){double eps=2e-5;V a=q,b=q;a[i]+=eps;b[i]-=eps;auto ea=p.evaluate(a),eb=p.evaluate(b);ge=std::max(ge,std::abs((ea.objective.a-eb.objective.a)/(2*eps)-e.objective.g[i]));he=std::max(he,((ea.objective.g-eb.objective.g)/(2*eps)-e.objective.H.col(i)).norm());}
 auto map=p.map(q);V fullr=residuals(f.evaluate(map.z));V expect=V::Zero(fullr.size());double total=residuals(e)[0];if(extension=="balanced")expect.setConstant(total/p.B.rows());else expect[extension=="grounded_first"?0:expect.size()-1]=total;double be=(fullr-expect).norm();bool pass=ge<1e-6&&he<1e-6&&be<1e-10;out<<c.name<<','<<extension<<','<<ge<<','<<he<<','<<be<<','<<p.B.cols()-p.B.fullPivLu().rank()<<','<<pass<<'\n';if(!pass)throw std::runtime_error("reduction_derivative_or_balance");}std::cout<<"reduction validation passed\n";}
void single(const fs::path&dir){std::ofstream out(dir/"one_step.csv");out<<std::setprecision(16)<<"case,h,gamma,extension,initial,form,budget,converged,energy_balance,stationarity,full_stationarity,objective,x_error_to_full,v_error_to_full,work_error_to_full,evaluations,ms,full_kkt_size,reduced_kkt_size\n";
 std::vector<Case> cases;for(auto n:{"scalar_release","scalar_mixed","radial_orbit","elastic_mixed","chain_mixed"})cases.push_back(make_case(n));cases.push_back(chain(8));cases.push_back(chain(8,100));
 for(auto&c:cases)for(double h:{1./120,1./30})for(double gamma:{.1,1.,10.}){double E=std::max(1e-6,energy(c.model,c.initial)-minimum_energy(c.model));auto cfg=configuration("implicit_midpoint_dg");cfg.gamma=gamma;CrossProblem f(c.model,c.initial,h,cfg,E,"implicit_midpoint_dg",true);
 for(std::string extension:{"balanced","grounded_first","grounded_last"}){Reduced p(f,extension);for(std::string init:{"BE","midpoint"}){V q=init=="BE"?p.initial():p.midpoint_initial();V z=p.map(q).z;Solve fullsolve=joint_solve(f,128,&z);State fullstate=f.state(fullsolve.z);for(int budget:{16,64,128}){Solve s=joint_solve(p,budget,&q);State r=p.state(s.z);auto map=p.map(s.z);auto ef=f.evaluate(map.z);double fullstation=stationarity(ef,p.full_dual(s));out<<c.name<<','<<h<<','<<gamma<<','<<extension<<','<<init<<",reduced,"<<budget<<','<<s.converged<<','<<s.primal<<','<<s.dual_residual<<','<<fullstation<<','<<s.objective<<','<<(r.x-fullstate.x).norm()<<','<<(r.v-fullstate.v).norm()<<','<<(map.z.tail(f.p.wcount)-fullsolve.z.tail(f.p.wcount)).norm()<<','<<s.evaluations<<','<<s.milliseconds<<','<<f.p.n+ef.rows.size()<<','<<p.p.n+1<<'\n';}
 out<<c.name<<','<<h<<','<<gamma<<','<<extension<<','<<init<<",full,128,"<<fullsolve.converged<<','<<fullsolve.primal<<','<<fullsolve.dual_residual<<','<<fullsolve.dual_residual<<','<<fullsolve.objective<<",0,0,0,"<<fullsolve.evaluations<<','<<fullsolve.milliseconds<<','<<f.p.n+f.evaluate(fullsolve.z).rows.size()<<','<<p.p.n+1<<'\n';}}
 std::cout<<c.name<<" h="<<h<<" gamma="<<gamma<<std::endl;
 }}
void trajectories(const fs::path&dir){std::ofstream out(dir/"trajectories.csv");out<<std::setprecision(16)<<"case,form,extension,initial,h,duration,steps,nonconverged,max_energy,max_primal,max_stationarity,position_rms,reference_gap,reference_certified,evaluations,ms\n";fs::create_directories(dir/"traces");
 for(auto name:{"scalar_release","scalar_mixed","radial_orbit","elastic_mixed","chain_mixed"})for(double h:{1./60,1./120})for(std::string form:{"full","reduced"})for(std::string extension:form=="full"?std::vector<std::string>{"balanced"}:std::vector<std::string>{"balanced","grounded_first","grounded_last"}){
 auto c=make_case(name);State s=c.initial,ref=s,ref2=s;double E0=energy(c.model,s),E=std::max(1e-6,E0-minimum_energy(c.model)),maxE=0,maxP=0,maxS=0,sumx=0,gap=0,ms=0;int bad=0,eval=0,done=0;auto cfg=configuration("implicit_midpoint_dg");std::ofstream trace(dir/"traces"/(std::string(name)+"_"+form+"_"+extension+"_"+std::to_string(h)+".csv"));trace<<std::setprecision(16)<<"t,energy";for(int i=0;i<dof(c.model);++i)trace<<",x"<<i<<",ref_x"<<i;trace<<'\n';
 for(int i=0;i<std::lround(5/h);++i){CrossProblem f(c.model,s,h,cfg,E,"implicit_midpoint_dg",true);Reduced p(f,extension);V q=p.midpoint_initial();Solve a;State next;if(form=="full"){V z=p.map(q).z;a=joint_solve(f,128,&z);next=f.state(a.z);}else{a=joint_solve(p,128,&q);next=p.state(a.z);}if(!finite(next)||next.x.norm()>1e5||std::abs(energy(c.model,next)-E0)/E>1e3)break;
 ref=reference_step(c.model,ref,h,64);ref2=reference_step(c.model,ref2,h,128);gap=std::max(gap,(ref.x-ref2.x).norm()+(ref.v-ref2.v).norm()/std::sqrt(E));if(!a.converged)++bad;maxE=std::max(maxE,std::abs(energy(c.model,next)-E0)/E);maxP=std::max(maxP,a.primal);maxS=std::max(maxS,a.dual_residual);sumx+=(next.x-ref2.x).squaredNorm()/c.model.count;eval+=a.evaluations;ms+=a.milliseconds;s=next;++done;trace<<(i+1)*h<<','<<energy(c.model,s);for(int k=0;k<dof(c.model);++k)trace<<','<<s.x[k]<<','<<ref2.x[k];trace<<'\n';}
 out<<name<<','<<form<<','<<extension<<",midpoint,"<<h<<",5,"<<done<<','<<bad<<','<<maxE<<','<<maxP<<','<<maxS<<','<<(done?std::sqrt(sumx/done):0)<<','<<gap<<','<<(gap<1e-5)<<','<<eval<<','<<ms<<'\n';std::cout<<"trajectory "<<name<<' '<<form<<' '<<extension<<' '<<h<<std::endl;
 }}
int main(int argc,char**argv){try{fs::path dir=argc>1?argv[1]:"results";fs::create_directories(dir);std::string mode=argc>2?argv[2]:"all";validate(dir);if(mode=="all"||mode=="single")single(dir);if(mode=="all"||mode=="trajectories")trajectories(dir);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
